   "intro": "导数回答的是“变化有多快”：函数在一点的变化率。它的定义是差商（平均变化率）的极限：\n\n$$f'(x_0)=\\lim_{\\Delta x\\to0}\\frac{f(x_0+\\Delta x)-f(x_0)}{\\Delta x}.$$\n\n几何上，导数就是曲线在这一点**切线的斜率**；物理上，位移对时间的导数就是速度。本章先建立导数概念，再系统给出求导法则（四则、复合、反函数）与基本公式，最后引入**微分**：把“变化”用自变量的变化线性地近似出来，这是后面近似计算与积分思想的伏笔。",
