   "summary": "**本章小结**\n\n1. 中值定理链条：Rolle → Lagrange → Cauchy。核心推论：\\(f'\\equiv0\\iff f\\) 常数；\\(f'\\ge0\\iff\\) 单调上升。\n2. 洛必达法则只用于 \\(\\frac00\\)、\\(\\frac\\infty\\infty\\) 型，用前先验证条件；可反复使用或与等价无穷小结合。\n3. 泰勒公式是“局部多项式逼近”，麦克劳林展开要熟记；它在近似计算、求极限（如 \\(\\lim\\frac{x-\\sin x}{x^3}\\)）、证明不等式中都很有用。\n4. 用导数画函数图像：单调与极值看一阶导，凹凸与拐点看二阶导，趋势看渐近线。\n\n**常见误区**\n- 极值点不一定是驻点（\\(|x|\\)），驻点不一定是极值点（\\(x^3\\)）。\n- 最值 ≠ 极值：闭区间最值要比较驻点、不可导点与端点。\n- \\(f''(x_0)=0\\) 不能直接断言拐点，要看二阶导是否变号。\n- 洛必达后极限不存在（振荡）时，原极限可能仍然存在（如 \\(\\lim_{x\\to\\infty}\\frac{x+\\sin x}{x}\\) 不能用洛必达但极限为 1）。",
