   "summary": "**本章小结**\n\n1. 定积分 = 黎曼和的极限；连续（或有界且有限个间断点）⇒ 可积。\n2. 性质：线性、区间可加、保序、估值、积分中值定理。\n3. 微积分基本定理：\\(\\Phi(x)=\\int_a^x f\\) 是原函数，\\(\\int_a^b f=F(b)-F(a)\\)——定积分由此变得可算。\n4. 定积分换元要换限；分部要代上下限；对称区间巧用奇偶性。\n\n**常见误区**\n- 黎曼和里的 \\(\\Delta x_i\\) 是区间长度，不是 \\(\\mathrm{d}x\\) 的“微小段”玄学。\n- \\(\\int_a^b f\\ge0\\) 推不出 \\(f\\ge0\\)（只能推出“几乎处处”，本课程暂不展开）。\n- 变上限积分求导忘记乘内层导数。\n- 换元不换限、分部忘记代端点。\n- 被积函数在区间内有间断点时，不能直接套牛顿–莱布尼茨（如 \\(\\int_{-1}^1\\frac1{x^2}\\) 是反常积分）。",
