   "intro": "定积分能算的不只是面积。只要某个量“在小区间上近似等于 \\(f(x)\\Delta x\\)，且误差是 \\(\\Delta x\\) 的高阶无穷小”，就可以用 \\(\\int f(x)\\,\\mathrm{d}x\\) 精确表示。这套“**微元法**”（元素法）把面积、体积、弧长、功、压力等统统纳入同一框架：\n\n1. **分割**：把整体切成小段；\n2. **近似**：每一小段上，把所求量近似为 \\(f(x)\\Delta x\\)（微元 \\(\\mathrm{d}A=f(x)\\mathrm{d}x\\)）；\n3. **求和取极限**：得到定积分。\n\n学完本章你会看到：物理与几何里那些“看起来不同”的公式，其实是同一个思想。",
