   "intro": "普通的定积分要求“区间有限 + 被积函数有界”。实际中常遇到两类“越界”情形：区间无穷（\\(\\int_1^\\infty\\frac{\\mathrm{d}x}{x^2}\\)），或被积函数在某点无界（\\(\\int_0^1\\frac{\\mathrm{d}x}{\\sqrt{x}}\\)）。它们统称**反常积分**，不能直接代上下限，要先“砍断”再取极限。\n\n反常积分的核心问题是**收敛性**：这个“面积”是有限的还是无穷的？直观上，\\(\\int_1^\\infty\\frac{\\mathrm{d}x}{x}\\) 的曲线很快趋近 0，可面积竟然是无穷大——这正说明“趋于 0 的速度”必须精确刻画。互动演示里把 \\(p\\) 从 1 拨到 1.01，观察面积从“发散”跳到“收敛”的临界。",
