   "intro": "“把无穷多个数加起来”是什么意思？\\(1+\\frac12+\\frac14+\\cdots=2\\) 可以直观理解，但 \\(1-1+1-1+\\cdots\\) 该等于多少？答案是不等于任何数——因为部分和 \\(S_n\\) 在 0 与 1 之间震荡，不收敛。\n\n级数的严格定义是：先算**部分和** \\(S_n=a_1+\\cdots+a_n\\)，再看 \\(S_n\\) 是否收敛。级数收敛 ⇔ 部分和数列收敛。于是级数的全部理论都可以“翻译”成数列极限的语言。本章要掌握：正项级数的三大判别法（比较、比值、根值）、交错级数的莱布尼茨判别法，以及“绝对收敛”与“条件收敛”的区别。",
