       "x": "去互动演示观察：几何级数 \\(\\sum(\\frac12)^n\\) 的部分和像台阶一样逼近 1；调和级数的部分和缓慢但坚定地增长（\\(S_{10000}\\approx9.79\\)）；交错调和级数则左右摇摆着逼近 \\(\\ln2\\)。“收敛与否”，本质是看部分和点列的走向。"
