       "title": "比较判别法",
       "x": "设 \\(\\sum a_n\\)、\\(\\sum b_n\\) 为正项级数，\\(a_n\\le b_n\\)：\\(\\sum b_n\\) 收敛 ⇒ \\(\\sum a_n\\) 收敛；\\(\\sum a_n\\) 发散 ⇒ \\(\\sum b_n\\) 发散。\n\n极限形式：若 \\(\\lim\\frac{a_n}{b_n}=c\\)，\\(0<c<+\\infty\\)，则两级数同敛散。常用比较对象：几何级数、p-级数 \\(\\sum\\frac1{n^p}\\)（\\(p>1\\) 收敛，\\(p\\le1\\) 发散）。"
