   "summary": "**本章小结**\n\n1. 收敛半径：\\(R=1/\\rho\\)（比值或根值公式）；端点单独判断得收敛域。\n2. 幂级数在收敛区间内：连续、可逐项积分、逐项求导，收敛半径不变。\n3. 展开三法：直接用泰勒公式（少用）、间接法（换元/求导/积分，常用）、解微分方程（选学）。\n4. 熟记五个基本展开式（几何、指数、正弦、余弦、对数、二项式）。\n\n**常见误区**\n- 求收敛域只算半径不管端点。\n- 逐项求导/积分后忘记检查端点（端点可能变）。\n- 间接展开时忽略收敛区间（如 \\(\\ln(1+x)\\) 的展开在 \\(x=1\\) 收敛于 \\(\\ln2\\)，\\(x=-1\\) 发散）。\n- 把“泰勒级数收敛”当“等于 \\(f\\)”（还需余项趋于 0）。",
