   "intro": "一元微分学处理“沿 x 轴的变化率”；多元函数有多个方向，于是出现**偏导数**（固定其它变量，只沿一个坐标方向求导）。但偏导数只是“切片”，函数在一点真正的线性近似要由**全微分**描述——它要求沿任何方向的变化都能被一个线性映射控制。\n\n本章主线：偏导数与全微分的关系（可微 ⇒ 连续、偏导存在；偏导存在/连续 ⇒ 可微）→ 复合函数链式法则（多元版的“剥洋葱”）→ 方向导数与梯度（函数增长最快的方向）→ 多元极值与条件极值。互动演示里，梯度箭头垂直于等高线、指向最陡上升方向，是最直观的几何画面。",
