       "ans": "偏导数 \\(f_x(0,0)=\\lim_{\\Delta x\\to0}\\frac{|\\Delta x|}{\\Delta x}\\) 不存在（左右极限 ±1），故偏导不存在，不可微。（曲面是圆锥面，原点有“尖”。）"
