   "summary": "**本章小结**\n\n1. 偏导数是“切片导数”；全微分是整体的线性近似。可微 ⇒ 连续 + 偏导存在；偏导连续 ⇒ 可微；偏导存在 ⇏ 可微。\n2. 链式法则：画依赖树，路径相乘再求和。\n3. 方向导数 \\(=\\nabla f\\cdot\\mathbf{u}\\)；梯度垂直于等高线、指向最陡上升方向。\n4. 极值：驻点 + 黑塞判别（\\(AC-B^2\\)）；条件极值用拉格朗日乘子法。\n\n**常见误区**\n- 认为偏导存在就可微/连续。\n- 链式法则漏项（少一条路径）或弄混 \\(\\partial u/\\partial x\\)。\n- 混合偏导直接换序而不检查连续性。\n- 把驻点当极值点（鞍点 \\(x^2-y^2\\) 反例）。",
