   "intro": "积分 \\(\\int_a^b f(x,y)\\mathrm{d}x\\) 的结果通常还依赖参数 \\(y\\)，于是得到一个**以参数为变量的函数** \\(F(y)\\)。这类“含参量积分”在数学物理中无处不在（如 \\(\\Gamma\\) 函数、傅里叶变换）。问题自然产生：\\(F(y)\\) 是否连续？能否对 \\(y\\) 求导（把导数搬进积分号）？能否再对 \\(y\\) 积分（交换积分次序）？\n\n答案与第十三章如出一辙：需要某种“一致”条件。对正常积分，只要被积函数连续，诸性质都成立；对反常积分，则要求**一致收敛**。本课程用“控制收敛”的思想统一处理：找到一个与参数无关的可积控制函数，就能放心地交换极限、积分与导数。",
