       "t": "def",
       "tag": "定义 20.2",
       "title": "第二类曲线积分",
       "x": "设 \\(\\mathbf{F}=(P(x,y),Q(x,y))\\) 为平面向量场，沿曲线 \\(C\\)（参数 \\(\\mathbf{r}(t)\\)，\\(\\alpha\\le t\\le\\beta\\)）的积分为\n\n$$\\int_C P\\,\\mathrm{d}x+Q\\,\\mathrm{d}y=\\int_\\alpha^\\beta\\left[P(x(t),y(t))x'(t)+Q(x(t),y(t))y'(t)\\right]\\mathrm{d}t.$$\n\n物理意义：\\(\\mathbf{F}\\) 是力，积分是沿 \\(C\\) 从起点到终点力所做的功 \\(W=\\int_C\\mathbf{F}\\cdot\\mathrm{d}\\mathbf{r}\\)。**与方向有关**：反向积分变号。绕闭曲线一周的积分叫**环量**，记 \\(\\oint_C\\)。"
