   "intro": "一重积分算“长度上的累积”（面积），**二重积分**算“面积上的累积”（体积）：把区域切成小方块，每块乘上函数值再求和取极限。它同样有两种“性格”：作为黎曼和的极限（定义），以及化为**累次积分**计算（先对 \\(y\\) 再对 \\(x\\)，像切面包片一样先算每片再叠加）。\n\n本章关键在“**把区域描述清楚**”：\\(x\\)-型区域 \\(a\\le x\\le b,\\ y_1(x)\\le y\\le y_2(x)\\) 先 \\(y\\) 后 \\(x\\)；必要时交换积分次序；圆域换**极坐标**。互动演示把“先切片后累积”两步走可视化：竖线切片的内层积分形成曲线，外层积分再把它下面的面积累积起来。",
