       "t": "def",
       "tag": "定义 21.1",
       "title": "二重积分",
       "x": "设 \\(f(x,y)\\) 在有界闭区域 \\(D\\) 上有定义。把 \\(D\\) 分割成若干小区域 \\(\\Delta\\sigma_i\\)（面积仍记 \\(\\Delta\\sigma_i\\)，直径最大值 \\(\\lambda\\to0\\)），任取 \\((\\xi_i,\\eta_i)\\in\\Delta\\sigma_i\\)，作和 \\(\\sum f(\\xi_i,\\eta_i)\\Delta\\sigma_i\\)。若极限存在且与分割、取点无关，称 \\(f\\) 在 \\(D\\) 上可积：\n\n$$\\iint_D f(x,y)\\,\\mathrm{d}\\sigma=\\lim_{\\lambda\\to0}\\sum_i f(\\xi_i,\\eta_i)\\Delta\\sigma_i.$$\n\n几何：\\(f\\ge0\\) 时是以 \\(D\\) 为底、\\(z=f\\) 为顶的曲顶柱体体积。连续函数在有界闭区域上必可积。"
